def _sep(v):
    L = len(v)
    if L == 2: return True
    h = L // 2
    R0, R1 = v[:h], v[h:]
    if any(R0[j]*R1[k] != R0[k]*R1[j]
           for j in range(h) for k in range(j+1, h)):
        return False
    return _sep(R0 if any(R0) else R1)
